// Draw tree A and tree B side by side. A node id present in both trees
// is the SAME object - drawn grey. Nodes only in B are the copied path.
const pbst = nb.get('pbst');
if (!pbst) return 'Run the Clojure cell first.';

const idsA = new Set(pbst.a.nodes.map(n => n.id));

function layout(tree) {
  const byId = {};
  tree.nodes.forEach(n => { byId[n.id] = n; });
  let x = 0;
  const pos = {};
  (function walk(id, depth) {
    if (id == null) return;
    const n = byId[id];
    walk(n.left, depth + 1);
    pos[id] = { x: x++, y: depth };
    walk(n.right, depth + 1);
  })(tree.root, 0);
  return { byId, pos, slots: x };
}

function render(tree, title, shared) {
  const { byId, pos, slots } = layout(tree);
  const W = 440, H = 300, PAD = 30;
  const px = id => PAD + (W - 2 * PAD) * (pos[id].x / Math.max(1, slots - 1));
  const py = id => PAD + 52 * pos[id].y;
  const parts = [];
  parts.push('<text x="' + (W / 2) + '" y="16" text-anchor="middle" font-size="13" fill="#94a3b8">' + title + '</text>');
  for (const n of tree.nodes) {
    for (const kid of [n.left, n.right]) {
      if (kid == null) continue;
      parts.push('<line x1="' + px(n.id) + '" y1="' + py(n.id) + '" x2="' + px(kid) +
        '" y2="' + py(kid) + '" stroke="#475569" stroke-width="1.5"/>');
    }
  }
  for (const n of tree.nodes) {
    const isShared = shared && idsA.has(n.id);
    const fill = shared ? (isShared ? '#334155' : '#b45309') : '#334155';
    const ring = shared && !isShared ? '#fbbf24' : '#64748b';
    parts.push('<circle cx="' + px(n.id) + '" cy="' + py(n.id) + '" r="15" fill="' + fill +
      '" stroke="' + ring + '" stroke-width="2"/>');
    parts.push('<text x="' + px(n.id) + '" y="' + (py(n.id) + 4) +
      '" text-anchor="middle" font-size="11" fill="#f8fafc">' + n.val + '</text>');
    parts.push('<text x="' + px(n.id) + '" y="' + (py(n.id) + 27) +
      '" text-anchor="middle" font-size="8" fill="#64748b">#' + n.id + '</text>');
  }
  return '<svg width="' + W + '" height="' + H + '" style="background:#0f172a;border-radius:8px">' +
    parts.join('') + '</svg>';
}

const newInB = pbst.b.nodes.filter(n => !idsA.has(n.id)).length;
console.log('tree B has', pbst.b.nodes.length, 'nodes,', newInB, 'newly allocated (amber),',
  pbst.b.nodes.length - newInB, 'shared (grey)');

return '<div style="display:flex;gap:14px;flex-wrap:wrap">' +
  render(pbst.a, 'tree A - before insert', false) +
  render(pbst.b, 'tree B - after (insert 42), amber = new', true) +
  '</div>';
